using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("List all users from the REST API.")]
    public async Task<string> ListUsers(
        [Description("Maximum number of results to return (1-100)")] int limit = 10,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing users with limit {Limit}", limit);
        var response = await httpClient.GetStringAsync($"/api/users?limit={limit}", cancellationToken);
        return response;
    }

    [McpServerTool, Description("Get a single user by their unique identifier.")]
    public async Task<string> GetUser(
        [Description("The unique user ID")] string userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        var response = await httpClient.GetAsync($"/api/users/{userId}", cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            return $"Error: User '{userId}' not found (HTTP {(int)response.StatusCode})";
        }

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        return content;
    }

    [McpServerTool, Description("Create a new user with the given name and email address.")]
    public async Task<string> CreateUser(
        [Description("Full name of the user")] string name,
        [Description("Email address")] string email,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating user {Name}", name);
        var payload = JsonSerializer.Serialize(new { name, email }, JsonOptions);
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");

        var response = await httpClient.PostAsync("/api/users", content, cancellationToken);
        var body = await response.Content.ReadAsStringAsync(cancellationToken);

        return response.IsSuccessStatusCode
            ? body
            : $"Error creating user (HTTP {(int)response.StatusCode}): {body}";
    }
}

